const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const smithIsland = ee.Geometry.Polygon([[
    [-76.1, 38.05],
    [-75.9, 38.05],
    [-75.9, 37.9],
    [-76.1, 37.9],
    [-76.1, 38.05]
  ]]);
  const year1 = 1999;
  const year2 = 2019;
  const start1 = ee.Date.fromYMD(year1, 1, 1);
  const end1 = ee.Date.fromYMD(year1, 12, 31);
  const start2 = ee.Date.fromYMD(year2, 1, 1);
  const end2 = ee.Date.fromYMD(year2, 12, 31);

  // 2. Data Acquisition & Processing Functions
  // Function to mask clouds, shadow, and snow for Landsat 4, 5, 7
  function maskL457(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 5).or(qa.bitwiseAnd(1 << 7));
    return image.updateMask(cloud.not());
  }

  // Function to mask clouds, shadow, and snow for Landsat 8
  function maskL8(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return image.updateMask(cloud.not());
  }

  // Function to calculate NDWI for different Landsat missions
  const getNDWI = (image, nir, green) => image.normalizedDifference([green, nir]).rename('ndwi');

  // Process a given year
  async function getLandArea(year, startDate, endDate, geometry) {
    let collection, l8_bands, l457_bands;
    if (year >= 2013) {
      collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(geometry)
        .map(maskL8);
      l8_bands = { nir: 'SR_B5', green: 'SR_B3' };
    } else if (year >= 1999) { // Use Landsat 7 for 1999
        collection = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
            .filterDate(startDate, endDate)
            .filterBounds(geometry)
            .map(maskL457);
        l457_bands = { nir: 'SR_B4', green: 'SR_B2' };
    } else { // Fallback to Landsat 5
        collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
            .filterDate(startDate, endDate)
            .filterBounds(geometry)
            .map(maskL457);
        l457_bands = { nir: 'SR_B4', green: 'SR_B2' };
    }

    const imageCount = await collection.size().getInfo();
    if (imageCount === 0) {
      return { area: null, count: 0 };
    }

    const composite = collection.median();
    const ndwi = (year >= 2013) ? getNDWI(composite, l8_bands.nir, l8_bands.green) : getNDWI(composite, l457_bands.nir, l457_bands.green);

    // Land is where NDWI is less than or equal to a threshold (e.g., 0)
    const landMask = ndwi.lte(0);
    const areaImage = ee.Image.pixelArea().updateMask(landMask);

    const stats = await areaImage.reduceRegion({
      reducer: ee.Reducer.sum().combine({
          reducer2: ee.Reducer.count(),
          sharedInputs: true
      }),
      geometry: geometry,
      scale: 30, // Native resolution for Landsat
      maxPixels: 1e9
    }).getInfo();

    const landArea = stats ? stats.area : null;
    const pixelCount = stats ? stats.count : 0;

    return { area: landArea, count: imageCount, pixels: pixelCount };
  }

  // 3. Calculation
  const result1999 = await getLandArea(year1, start1, end1, smithIsland);
  const result2019 = await getLandArea(year2, start2, end2, smithIsland);

  // 4. Validation & Final Answer
  console.log(`1999: Images found: ${result1999.count}`);
  console.log(`2019: Images found: ${result2019.count}`);

  if (result1999.count === 0 || result2019.count === 0) {
    console.log("Evidence: No images found for one or both years.");
    console.log("A");
    return;
  }

  if (!result1999.pixels || !result2019.pixels) {
      console.log("Evidence: No valid land pixels found after cloud masking.");
      console.log("C2");
      return;
  }

  const area1999_km2 = result1999.area / 1e6;
  const area2019_km2 = result2019.area / 1e6;

  console.log(`1999 Land Area (km2): ${area1999_km2.toFixed(2)} from ${result1999.pixels} pixels`);
  console.log(`2019 Land Area (km2): ${area2019_km2.toFixed(2)} from ${result2019.pixels} pixels`);

  if (result1999.area === null || result2019.area === null) {
      console.log("Evidence: Calculation failed for one or both years.");
      console.log("C3");
  } else if (area2019_km2 < area1999_km2) {
      console.log("Evidence: The land area in 2019 is less than in 1999.");
      console.log("A");
  } else {
      console.log("Evidence: The land area in 2019 is not less than in 1999.");
      console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log("D");
});
